 t=open(f).read();d=int(re.search(r'DAY: (\d+)',t).group(1));p=int(re.search(r'PR_(\d+)',t).group(1));q=int(re.search(r'SEQUENCE_NO: (\d+)',t).group(1));sseq[d,q]=p
