const r = await tools.exec_command({"cmd":"python - <<'PY'
import os,re,json,csv,glob,collections,numpy as np,time
T=time.time()
def parse(path,kind):
 s=open(path).read(); ext=path.rsplit('.',1)[-1]
 if ext=='json':
  a=json.loads(s)['items']; return [(int(x['prod_id'][2:])-1,int(x.get('qty',x.get('delivered_qty')))) for x in a]
 if ext=='csv': return [(int(x.split(';')[0][2:])-1,int(x.split(';')[1])) for x in s.splitlines()[1:] if x]
 if kind=='order':
  m=re.findall(r'deliver (\d+) units of product P_(\d+)',s)
  if m:return [(int(p)-1,int(q)) for q,p in m]
  return [(int(p)-1,int(q)) for p,q in re.findall(r'ORDER_PRODUCT: P_(\d+) \| ORDER_QTY: (\d+)',s)]
 m=re.findall(r'delivered (\d+) units of product P_(\d+)',s)
 if m:return [(int(p)-1,int(q)) for q,p in m]
 return [(int(p)-1,int(q)) for p,q in re.findall(r'PRODUCT: P_(\d+) \| DELIVERED_QTY: (\d+)',s)]
orders={}
for f in glob.glob('raw_orders/*'):
 d,s=map(int,re.search(r'day_(\d+)_S_(\d+)',f).groups());orders[d,s-1]=parse(f,'order')
supp={}
for f in glob.glob('raw_supplier_receipts/*'):
 d,p=map(int,re.search(r'day_(\d+)_PR_(\d+)',f).groups());supp[d,p-1]=parse(f,'supp')
sseq={}
for f in glob.glob('raw_wholesaler_receipts/*'):
 t=open(f).read();d=int(re.search(r'DAY: (\d+)',t).group(1));p=int(re.search(r'PR_(\d+)',t).group(1))-1;q=int(re.search(r'SEQUENCE_NO: (\d+)',t).group(1));sseq[d,q]=p
storeseq={};totals={}
for f in glob.glob('raw_wholesaler_store_receipts/*'):
 t=open(f).read();d=int(re.search(r'DAY: (\d+)',t).group(1));s=int(re.search(r'S_(\d+)',t).group(1))-1;q=int(re.search(r'SEQUENCE_NO: (\d+)',t).group(1));z=int(re.search(r'TOTAL_DELIVERED_UNITS: (\d+)',t).group(1));storeseq[d,q]=s;totals[d,s]=z
# allocate wholesale, queues entries pr,qty,day; delivery map
winv=[collections.deque() for _ in range(30)];delivery={}
for d in range(1,366):
 for q in range(1,61):
  pr=sseq[d,q]
  for p,n in supp[d,pr]: winv[p].append([pr,n,d])
 for q in range(1,11):
  st=storeseq[d,q]; got=0
  for p,n in orders.get((d,st),[]):
   out=[]
   while n and winv[p]:
    z=min(n,winv[p][0][1]);n-=z;got+=z;winv[p][0][1]-=z
    out.append((winv[p][0][0],z,winv[p][0][2]))
    if winv[p][0][1]==0:winv[p].popleft()
   if out:delivery[d,st,p]=out
  assert got==totals[d,st]
print('parsed+allocated seconds',round(time.time()-T,2),'delivery keys',len(delivery))
# replay consumer demand/sale, inventory entries pr,qty,supday
D=np.zeros((366,10,60,30),dtype=np.uint8); Sold=np.zeros_like(D); Mask=np.zeros(D.shape,dtype=np.uint64)
sinv=[[collections.deque() for p in range(30)] for s in range(10)]
errs=0;nrows=0
with open('sales_log.csv') as f:
 reader=csv.DictReader(f); lastds=None; lastp=99;c=-1
 for r in reader:
  d=int(r['Day']);st=int(r['Store_ID'][2:])-1;p=int(r['Product_ID'][2:])-1
  ds=(d,st)
  if ds!=lastds:
   if lastds:
    pd,ps=lastds
    for pp in range(30):
     for pr,z,bd in delivery.get((pd,ps,pp),[]):sinv[ps][pp].append([pr,z,bd])
   lastds=ds;lastp=99;c=-1
  if p<=lastp:c+=1
  lastp=p
  dem=int(r['Reported_Demand']); sold=int(r['Sold_Quantity']); D[d,st,c,p]=dem;Sold[d,st,c,p]=sold;nrows+=1
  remain=sold;mask=0
  while remain and sinv[st][p]:
   z=min(remain,sinv[st][p][0][1]);remain-=z;sinv[st][p][0][1]-=z;mask|=np.uint64(1)<<np.uint64(sinv[st][p][0][0])
   if sinv[st][p][0][1]==0:sinv[st][p].popleft()
  if remain:errs+=1
  Mask[d,st,c,p]=mask
# final delivery after d365 irrelevant
print('replay seconds',round(time.time()-T,2),'rows',nrows,'errs',errs,'remaining store stock',sum(x[1] for s in sinv for p in s for x in p))
# calendar normalize D by per-day product mean, with floor. pair baselines after norm
# Naive future demand by exposed event: aggregate raw ratios offsets means per PR/product
# Normalize each D by product-day mean relative product overall, avoid bad feedback but shared.
Ncons=np.array([60,45,43,53,53,60,42,55,57,51])
cal=np.zeros((366,30),float)
for d in range(1,366):
 for p in range(30):cal[d,p]=sum(D[d,s,:Ncons[s],p].sum() for s in range(10))/Ncons.sum()
# pair baseline using D/cal
base=np.zeros((10,60,30),float)
for s in range(10): base[s,:Ncons[s],:]=np.mean(D[1:,:, :, :][:,s,:Ncons[s],:]/np.maximum(cal[1:,None,:],.1),axis=0)
# normalized outcome D /(cal*base); base makes normal around1
Y=np.zeros(D.shape,dtype=np.float32)
for d in range(1,366):
 for s in range(10):Y[d,s,:Ncons[s],:]=D[d,s,:Ncons[s],:]/np.maximum(cal[d,None,:]*base[s,:Ncons[s],:],.05)
# cap huge due rare pairs, and restrict pair baseline meaningful
Y=np.clip(Y,0,5)
# Each mask exposure event. compute means offsets buckets, requiring sold>0 and future <=365
for p in range(30):
 vals=[]
 for pr in range(60):
  ex=(Mask[:,:,:,p] & (np.uint64(1)<<np.uint64(pr)))!=0
  idx=np.argwhere(ex)
  # one outcome mean per event per bucket
  ms=[]
  for lo,hi in [(1,3),(4,7),(8,14),(15,21)]:
   zz=[]
   for d,s,c in idx:
    if d+hi<=365:zz.append(Y[d+lo:d+hi+1,s,c,p].mean())
   ms.append(float(np.mean(zz)) if zz else np.nan)
  vals.append((ms[0],pr+1,len(idx),*ms))
 vals.sort()
 print('P',p+1,'LOW',[(pr,n,tuple(round(x,2) for x in ms)) for _,pr,n,*ms in vals[:10]],'HIGH',[(pr,n,round(a,2)) for a,pr,n,*_ in vals[-3:]])
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":30000});
text(r.output);

